\begin{exercise}
\label{prob:lie-group-exp-surjective}
\dcref{ch6:6-13}
\uses{prob:lie-group-bi-invariant-metric}

Let $G$ be a connected compact Lie group. Show that the Lie group exponential map of $G$ is surjective. [Hint: Use Problem 5-8.]
\end{exercise}

